head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07220";
scwin.toolTip = null;
scwin.dts_List = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.toolTip = $c.util.getComponent('toolTip');
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        await scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07220.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bzProcsNo", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } },
        { childId: "ipt_listTpClssCd", fn: function () { return String((dma_pageContext.get("listTpClssCd") ?? "")); } },
        { childId: "ipt_bzProcsNo_2", fn: function () { return String((dma_pageContext.get("bzProcsNo") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        form = (document.preListForm || { elements: [] });
        scwin.setEditMode(null);
        loadTp = 'null';
        if ("32" !== "${commonInfo. list_procs_stat_cd}") {
            $c.util.getComponent('AcptBttn').visable = false;
            $c.util.getComponent('img_9').visable = false;
            $c.util.getComponent('AcptBttn').src = "/img/btn_Acpt_d.gif";
            $c.util.getComponent('img_9').src = "/img/btn_reject_d.gif";
            if ("" === "" + dma_commonInfo.get("listProcsStatCd") + "") {
                $c.util.getComponent('AcptBttn').setStyle('visibility', "hidden");
                $c.util.getComponent('img_9').setStyle("visibility", "hidden");
            }
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07220.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldstf07220: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_doProcs_onclick
 * @description btn_doProcs 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doProcs_onclick = async function(e){
    try {
        await scwin.doProcs(33)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07220.btn_doProcs_onclick' }); }
};

/**
 * @method
 * @name btn_doProcs_2_onclick
 * @description btn_doProcs_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_doProcs_2_onclick = async function(e){
    try {
        await scwin.doProcs(37)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07220.btn_doProcs_2_onclick' }); }
};

/**
 * @method
 * @name grd_formFileList_oncellclick
 * @description grd_formFileList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formFileList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_attachList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_attachList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["useYn"]==='Y') { await scwin.downloadFile(r["attachFileSeq"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList.oncellclick' });
    }
};

/**
 * @method
 * @name grd_formFileList_2_oncellclick
 * @description grd_formFileList_2 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formFileList_2_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_attachList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_attachList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: downloadFile (인자 미해석) */
        if (r["useYn"]==='Y') { await scwin.downloadFile(r["attachFileSeq"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formFileList_2.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, BBS_TP_CD, LD_MKT_TP"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_ID, SCREN_PROCES_TP_CD, BBS_TP_CD, LD_MKT_TP", unresolved: "query_param:SCREN_ID,SCREN_PROCES_TP_CD,BBS_TP_CD,LD_MKT_TP" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/lstinvstg/ListCommBoard.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07220.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name tx_downloadFile
 * @description download File 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile = async function () {
    const sbmOptions = {
        id: "tx_downloadFile",
        method: "post",
        action: "/lstinvstg/ListPrelmInvstg.do",
        ref: "dma_downloadFileReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_doProcs_xhr
 * @description do Procs xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_doProcs_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_doProcs_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_doProcs_xhr", unresolved: "action:self_submit:tx_doProcs_xhr" };
};

/**
 * @method
 * @name grd_formFileList_fmt_column3
 * @description grd form File List fmt column3 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formFileList_fmt_column3 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_attachList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "useYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: column3 (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_formFileList.column3" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_formFileList_2_fmt_column3
 * @description grd form File List 2 fmt column3 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formFileList_2_fmt_column3 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_attachList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "useYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: column3 (image)'), String(data ?? '')) + '</a>'; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_formFileList_2.column3" }); return String(data ?? ''); }
};

/**
 * @method
 * @name setEditMode
 * @description set Edit Mode 처리
 * @param {*} tp tp
 * @returns {void}
 * @hidden N
 */
scwin.setEditMode = function (tp) {

    let div;
    let files;
    const chkObj = document.getElementsByName('useYn');
    // var editObj = document.getElementsByName('editYn');
    const itmObj = document.getElementsByName('fileItmNm');
    // var remkObj = document.getElementsByName('remk');

    for(let i = 0;i<chkObj.length;i++){
        // files = form['attachFiles['+i+']'];
        // files.disabled = true;
        chkObj[i].disabled = true;
        itmObj[i].readOnly = true;
        // remkObj[i].readOnly = true;
    }

    for(let i = "${fn:length(formFileList)}";i<chkObj.length;i++){
        chkObj[i].checked = true;
    }

};

/**
 * @method
 * @name isNotRelated
 * @description is Not Related 처리
 * @param {*} tmpObj tmpObj
 * @returns {void}
 * @hidden N
 */
scwin.isNotRelated = function (tmpObj) {
    const objIdx = scwin.getObjIdx(tmpObj, tmpObj.name);
    const fileObj = form['attachFiles['+ objIdx +']'];
    const itmObj = document.getElementsByName('fileItmNm');
    if (tmpObj.checked === true) {
        fileObj.disabled = true;
        if (objIdx >= $) {
            fn: length(formFileList);
        }
        itmObj[objIdx].readOnly = true;
    } else {
        fileObj.disabled = false;
        if (objIdx >= $) {
            fn: length(formFileList);
        }
        itmObj[objIdx].readOnly = false;
    }
};

/**
 * @method
 * @name getObjIdx
 * @description get Obj Idx 처리
 * @param {*} tmpObj tmpObj
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.getObjIdx = function (tmpObj, ver) {
    let idx;
    const chkObj = document.getElementsByName(ver);
    for (let i = 0; i < chkObj.length; i++) {
        if (chkObj[i] === '[object]') {
            if (chkObj[i] === tmpObj) {
                idx = i;
                break;
            }
        }
    }
    return idx;
};

/**
 * @method
 * @name hideTitle
 * @description hide Title 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.hideTitle = function (ver) {
    scwin.toolTip.style.visibility = "hidden";
};

/**
 * @method
 * @name doProcs
 * @description do Procs 처리
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.doProcs = async function (listProcsStatCd) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider
    if ("32" !== "${commonInfo. list_procs_stat_cd}") {
        await $c.win.alert(" 이미 처리된 건입니다.");
        return;
    }
    let msg = null;
    const msg1 = "접수처리 하시겠습니까?";
    const msg2 = "반려처리 하시겠습니까?";
    const msg3 = "위원회 심사대상으로 설정하시겠습니까?";
    let isComiteYn = null;
    if ("33" === listProcsStatCd) {
        msg = msg1;
    } else {
        msg = msg2;
    }
    const rse = await $c.win.confirm(msg, 1);
    if (!rse) {
        return;
    } else {
        if ("33" === listProcsStatCd) {
            const rse1 = await $c.win.confirm(msg3, 2);
            if (rse1 === true) {
                isComiteYn = "Y";
            } else {
                isComiteYn = "N";
            }
        } else {
            isComiteYn = "";
        }
    }
    let url = '/lstinvstg/LstInvstgCommon.do?method=processPremInvstgApp';
    url += "&BZ_PROCS_NO=" + $c.util.getComponent('ipt_bzProcsNo').getValue();
    url += "&LIST_INVSTG_BZ_TP_CD=120";
    url += "&LIST_PROCS_STAT_CD=" + listProcsStatCd;
    url += "&PROCS_EMP_NO=" + $c.session.getUserInfo("empNo");
    url += "&COMITE_INVSTG_OBJ_YN=" + isComiteYn;
    const frm = (document.procsForm || { elements: [] });
    frm.action = url;
    await scwin.tx_doProcs_xhr();
    const fr_fn_list_sync = $c.win.getParent().fn_list_sync;
    fr_fn_list_sync();
    $c.win.closePopup();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseXML responseXML
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onCompleteResponse = async function (responseXML) {
    if ((responseXML == null) || ('' === responseXML)) {
        await $c.win.alert("처리 중 오류가 발생하였습니다.");
    } else {
        const xmlDoc = xmlHttp.responseXML;
        let resultProcs = "";
        resultProcs = xmlDoc.getElementsByTagName("result")[0].firstChild.nodeValue;
        if (("" !== resultProcs) && ("-1" !== resultProcs)) {
            await $c.win.alert("정상처리되었습니다.");
            $c.util.getComponent('AcptBttn').visable = false;
            $c.util.getComponent('img_9').visable = false;
            $c.util.getComponent('AcptBttn').src = "/img/btn_Acpt_d.gif";
            $c.util.getComponent('img_9').src = "/img/btn_reject_d.gif";
        } else {
            await $c.win.alert("비정상 처리되었습니다.");
        }
    }
};

/**
 * @method
 * @name downloadFile
 * @description download File 처리
 * @param {*} attachFileSeq attachFileSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadFile = async function (attachFileSeq) {

    const gubun = "" + dma_pageContext.get("listTpClssCd") + "" ;

    if(
        $c.session.getUserInfo("depCd") === '2500' || $c.session.getUserInfo("depCd") === '2520' || $c.session.getUserInfo("depCd") === '2540'
        || $c.session.getUserInfo("depCd") === '3300' || $c.session.getUserInfo("depCd") === '3320' || $c.session.getUserInfo("depCd") === '3330' || $c.session.getUserInfo("depCd") === '3350' || $c.session.getUserInfo("depCd") === '3310'
        || $c.session.getUserInfo("depCd") === '3E00' || $c.session.getUserInfo("depCd") === '3E10' || $c.session.getUserInfo("depCd") === '3E20' || $c.session.getUserInfo("depCd") === '3E30' || $c.session.getUserInfo("depCd") === '3E40'
        || $c.session.getUserInfo("depCd") === '2615' || $c.session.getUserInfo("depCd") === '3G20' ||( $c.session.getUserInfo("depCd") === '3510' && gubun === '02') || $c.session.getUserInfo("depCd") === '3050'  || $c.session.getUserInfo("depCd") === '3E50'
    ) {
        const obj = (document.downloadForm || { elements: [] });
        obj.action='/lstinvstg/ListPrelmInvstg.do';
        $c.util.getComponent("dma_scriptDts_ListReq").set("method", 'downloadFile');
        $c.util.getComponent("dma_downloadFileReq").set("attachFileSeq", attachFileSeq);
        await scwin.tx_downloadFile();
    }else {
        await $c.win.alert('파일 열람 권한이 없습니다');
    }

};
